+    }
+
+    bool run() {
+        return  array_double() &&
+                array_int() &&
+                array_unsigned() &&
+                object() &&
+                docs() &&
+                number_parsing_error() &&
+                incorrect_type_error() &&
+                json_pointer_test() &&
